sys_script_include.script:
var WrkfrcExpAMCalibrationUtil = Class.create();
WrkfrcExpAMCalibrationUtil.prototype = {

    initialize: function() {},

    runFixScript: function() {

        var LOG = '[Alert Management Calibration] ';
        var errors = [];
        var logs = [];
        var appid = '';

        /* =====================================================
         * Helper functions 
         * ===================================================== */

        // SUCCESS logs
        function logInfo(name, value) {
            logs.push({
                name: name,
                status: true,
                message: value || ''
            });
            gs.info(LOG + name + ' - ' + value);
        }

        // ERROR logs
        function logError(name, value) {
            errors.push(name);
            logs.push({
                name: name,
                status: false,
                message: value || 'Failed'
            });
            gs.error(LOG + name + ' - ' + value);
        }
        // WARN logs (a configuration state, not a failure)
        function logWarn(name, value) {
            errors.push(name);
            logs.push({
                name: name,
                status: false,
                message: value || 'Failed'
            });
            gs.warn(LOG + name + ' - ' + value);
        }

        function validateExists(table, query, label) {
            var existsGr = new GlideRecordSecure(table);
            for (var f in query) {
                existsGr.addQuery(f, query[f]);
            }
            existsGr.query();

            if (!existsGr.hasNext()) {
                gs.info(label, 'Missing');
            } else {
                gs.info(label, 'Validated');
            }
        }

        function getScopeSysID(name) {
            var sysId = gs.getCurrentApplicationId();

            if (sysId) {
                appid = sysId;

                gs.info('Scope', name);
            } else {
                gs.info('Scope', 'Not found: ' + name);
            }
        }

        /* =====================================================
         * API STATUS CHECK
         *
         * This verifies connectivity only. It deliberately does NOT refresh the tenant
         * list - that is done by the HP WXP AM Tenant Config widget, which reads the
         * response body and upserts x_hpws_wrkfrcexpam_tenant_list. Headers here are kept
         * identical to the widget's so a passing check proves the same path works.
         * ===================================================== */

        function validateAPIConnection() {

            var apiKey = gs.getProperty('x_hpws_wrkfrcexpam.api.fastn.api.key');
            var baseUrl = gs.getProperty('x_hpws_wrkfrcexpam.fastn_api_baseurl');
            var tenantId = gs.getProperty('x_hpws_wrkfrcexpam.tenants');
            var spaceId = gs.getProperty('x_hpws_wrkfrcexpam.fastn.space.id');

            // NOT CONFIGURED
            if (!apiKey) {
                logWarn('API Status', 'Not Configured');
                return;
            }

            // Missing dependencies 
            if (!baseUrl || !tenantId || !spaceId) {
                logWarn('API Status', 'Configured but Missing Required Properties');
                return;
            }

            try {

                var endpoint = baseUrl + '/api/v1/getTenantsChildren';

                var r = new sn_ws.RESTMessageV2(); //'HP  WXP Alert Management','Get Customers of Partner'
                r.setEndpoint(endpoint);
                r.setHttpMethod('POST');

                r.setRequestHeader('Content-Type', 'application/json');
                r.setRequestHeader('fastn-space-id', spaceId);
                r.setRequestHeader('stage', 'LIVE');
                r.setRequestHeader('x-fastn-api-key', apiKey);
                r.setRequestHeader('x-fastn-space-tenantid', tenantId);

                r.setRequestBody(JSON.stringify({
                    input: {}
                }));

                var response = r.executeAsync();
                var status = response.getStatusCode();

                if (status >= 200 && status < 300) {
                    logInfo('API Status', 'Configured & Connected');
                    logInfo('Tenants', 'Connection verified - open Tenant Configuration and click Refresh to load them');
                } else {
                    logError('API Status', 'Configured but Not Connected (' + status + ')');
                }

            } catch (e) {
                logError('API Status', 'Configured but Error: ' + e.message);
            }
        }

        /* =====================================================
         * START
         * ===================================================== */

        gs.info(LOG + 'Started');

        try {

            /* =====================================================
             * URL Calibration
             * ===================================================== */

            getScopeSysID('x_hpws_wrkfrcexpam');

            logInfo('URL Calibration', 'Done');

            /* =====================================================
             * API Status
             * ===================================================== */
            validateAPIConnection();



        } catch (e) {
            logError('Unhandled failure', e.message);
        }

        var finalStatus = errors.length === 0;

        return {
            success: finalStatus,
            message: finalStatus ? 'Setup completed' : 'Setup failed',
            logs: logs
        };
    },

    resetSetup: function() {
        var LOG = '[Alert Management Calibration - RESET] ';


        try {


            gs.setProperty('x_hpws_wrkfrcexpam.api.fastn.api.key', '');
            gs.setProperty('x_hpws_wrkfrcexpam.fastn_api_baseurl', '');
            gs.setProperty('x_hpws_wrkfrcexpam.tenants', '');
            gs.setProperty('x_hpws_wrkfrcexpam.fastn.space.id', '');
            gs.setProperty('x_hpws_wrkfrcexpam.tenant.type', '');
            gs.setProperty('x_hpws_wrkfrcexpam.notify_failure_group', '');

            gs.info(LOG + 'Properties cleared');


            var tenantGr = new GlideRecordSecure('x_hpws_wrkfrcexpam_tenant_list');
            tenantGr.query();
            tenantGr.deleteMultiple();


            gs.info(LOG + 'AM Tenant table cleared (all records deleted)');


            return {
                success: true,
                message: 'Setup reset successful'
            };


        } catch (e) {
            gs.error(LOG + e.message);


            return {
                success: false,
                message: e.message
            };
        }
    },

    type: 'WrkfrcExpAMCalibrationUtil'
};
